import{_ as o,C as a,c as n,o as s,a3 as t,G as l}from"./chunks/framework.Dokpd4od.js";const f=JSON.parse('{"title":"Reporting overview","description":"","frontmatter":{},"headers":[],"relativePath":"master/finance/reporting/index.md","filePath":"master/finance/reporting/index.md","lastUpdated":1793074831000}'),i={name:"master/finance/reporting/index.md"};function h(d,e,g,p,c,u){const r=a("ImagePopup");return s(),n("div",null,[e[0]||(e[0]=t('<h1 id="reporting-overview" tabindex="-1">Reporting overview <a class="header-anchor" href="#reporting-overview" aria-label="Permalink to &quot;Reporting overview&quot;">​</a></h1><p>Reports turn your journal entries into answers: how much you own, how much you earned, and who owes you money. Aureus has seven reports. They read the posted entries of your company, so a draft invoice does not show up until you confirm it.</p><blockquote><p><strong>In simple words:</strong> Confirm your documents, then open a report to see the result. Reports never change your data.</p></blockquote><p>Reports exist in the Accounting app only. Open <code>Accounting → Reporting</code>. The Invoices app has no reporting menu.</p><h2 id="the-seven-reports" tabindex="-1">The seven reports <a class="header-anchor" href="#the-seven-reports" aria-label="Permalink to &quot;The seven reports&quot;">​</a></h2><p>The left side of every report page groups them:</p><ul><li><strong>Statement Reports</strong><ul><li><a href="./balance-sheet.html">Balance Sheet</a>: what you own and owe on a date.</li><li><a href="./profit-and-loss.html">Profit &amp; Loss</a>: revenue, expenses and net profit in a period.</li></ul></li><li><strong>Audit Reports</strong><ul><li><a href="./general-ledger.html">General Ledger</a>: every account with its movements.</li><li><a href="./trial-balance.html">Trial Balance</a>: the debit and credit totals per account.</li></ul></li><li><strong>Partner Reports</strong><ul><li><a href="./partner-ledger.html">Partner Ledger</a>: the balance of each customer and vendor.</li><li><a href="./aged-receivable-and-payable.html">Aged Receivable and Aged Payable</a>: open amounts by age.</li></ul></li></ul><h2 id="shared-controls" tabindex="-1">Shared controls <a class="header-anchor" href="#shared-controls" aria-label="Permalink to &quot;Shared controls&quot;">​</a></h2>',8)),l(r,{src:"/images1/finance/reporting_menu_and_filters.png",alt:"A report page (Profit & Loss) with the Statement/Audit/Partner Reports list on the left, Date Range and Journals on top, and the Export to Excel and E"}),e[1]||(e[1]=t('<ul><li><strong><em>Date Range:</em></strong> Pick a period from the calendar. Quick choices are <strong>Today</strong>, <strong>Yesterday</strong>, <strong>This Month</strong>, <strong>Last Month</strong>, <strong>This Quarter</strong>, <strong>Last Quarter</strong>, <strong>This Year</strong> and <strong>Last Year</strong>.</li><li><strong><em>Journals:</em></strong> Pick one or more journals to limit the report. Leave it empty to include all.</li><li><strong><em>Export to Excel</em></strong> and <strong><em>Export to PDF:</em></strong> Download the report you see. On the partner reports the buttons read <strong>Export Excel</strong> and <strong>Export PDF</strong>.</li><li><strong><em>Expand All</em></strong> and <strong><em>Collapse All:</em></strong> Open or close the detail rows. They are on the General Ledger, Partner Ledger and the aged reports.</li></ul><p>The Balance Sheet, Profit &amp; Loss, General Ledger, Trial Balance and Partner Ledger share the <strong>Date Range</strong>. The aged reports use <strong>As of</strong> instead.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The default range is the current month. If the report looks empty, pick a range that has data. Click the <strong>Date Range</strong> field and choose a ready-made range (<strong>Today</strong>, <strong>Yesterday</strong>, <strong>This Month</strong>, <strong>Last Month</strong>, <strong>This Quarter</strong>, <strong>Last Quarter</strong>, <strong>This Year</strong> or <strong>Last Year</strong>), or pick two days on the calendar, then click <strong>Apply</strong>. In the sample data the entries are dated July 2026, so choose <strong>Last Quarter</strong>.</p></div><h2 id="good-habits" tabindex="-1">Good habits <a class="header-anchor" href="#good-habits" aria-label="Permalink to &quot;Good habits&quot;">​</a></h2><ul><li>Confirm all invoices, bills and payments before you read a report.</li><li>Compare the <strong>Trial Balance</strong> totals. Debit and credit must match.</li><li>Use the <strong>Journals</strong> filter to look at sales only or bank only.</li><li>Export a PDF when you need to share the report.</li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../accounting-entries/journal-entries.html">Journal entries</a></li><li><a href="./../accounting-entries/journal-items.html">Journal items</a></li><li><a href="./../get-started/chart-of-accounts.html">Chart of accounts</a></li></ul>',7))])}const _=o(i,[["render",h]]);export{f as __pageData,_ as default};
